import 'dart:convert';
import 'dart:io';

import 'package:cohabit_analysis/cohabit_analysis.dart';
import 'package:test/test.dart';

/// Reads a committed fixture (generated by `tool/generate_fixtures.py`).
Map<String, Object?> fixture(String name) =>
    jsonDecode(File('test/fixtures/$name').readAsStringSync())
        as Map<String, Object?>;

/// Matches [expected] to within a relative `1e-9` (absolute near zero).
Matcher closeTo9(num expected) =>
    closeTo(expected, 1e-9 * (expected.abs() < 1 ? 1 : expected.abs()));

/// Small deterministic generator (xorshift32), so simulations never change.
class Rng {
  Rng(this._state);
  int _state;

  double next() {
    _state ^= (_state << 13) & 0xFFFFFFFF;
    _state ^= _state >> 17;
    _state ^= (_state << 5) & 0xFFFFFFFF;
    _state &= 0xFFFFFFFF;
    return _state / 0x100000000;
  }

  bool chance(double p) => next() < p;
}

/// A two-state chain that keeps its state with probability [stay].
List<int> runs(Rng rng, int days, double stay) {
  final v = List<int>.filled(days, 0);
  v[0] = rng.chance(0.5) ? 1 : 0;
  for (var t = 1; t < days; t++) {
    v[t] = rng.chance(stay) ? v[t - 1] : 1 - v[t - 1];
  }
  return v;
}

PairResult pair(AnalysisResult r, String from, String to, [int lag = 0]) => r
    .pairs
    .singleWhere((p) => p.fromId == from && p.toId == to && p.lag == lag);
